WITH p AS (SELECT coalesce(%s::text,'') ma_vt,coalesce(%s::text,'') step_code,coalesce(%s::text,'') ma_nh,%s::integer uid,%s::integer lim),s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR coalesce(u.ds_branchs,'')='' all_branch FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT row_number() OVER(ORDER BY q.ma_vt,q.step_code,q.ma_nh_chi_tieu) stt,q.ma_vt,v.ten_vt,q.kieu_th,q.step_code,q.ma_nh_chi_tieu,q.process_yn,q.ly_do_thay_doi,q.status,q.date0,q.time0,q.date2,q.time2,count(*) OVER() total FROM public.qcdmvt q LEFT JOIN public.dmvt v ON v.ma_vt=q.ma_vt CROSS JOIN s WHERE s.ok IS NOT NULL AND (s.ma_vt='' OR q.ma_vt=ANY(string_to_array(s.ma_vt,','))) AND (s.step_code='' OR q.step_code=ANY(string_to_array(s.step_code,','))) AND (s.ma_nh='' OR q.ma_nh_chi_tieu=ANY(string_to_array(s.ma_nh,','))) AND (s.all_branch OR coalesce(v.ds_ma_dvcs,'')='' OR EXISTS(SELECT 1 FROM unnest(string_to_array(s.bs,',')) x WHERE x=ANY(string_to_array(v.ds_ma_dvcs,',')))) ORDER BY q.ma_vt,q.step_code,q.ma_nh_chi_tieu LIMIT (SELECT lim FROM p);
